sys_script_include.script:
var BNBCertUserUtils = Class.create();

BNBCertUserUtils.prototype = {

	grpCertExterno: null,
	grpCertInterno: null,
	grpInstalaCert: null,

	initialize: function(){
		this.grpCertExterno = this.getSysUserGroup("sn_disco_certmgmt.BNB_certificados_externos");
		this.grpCertInterno = this.getSysUserGroup("sn_disco_certmgmt.BNB_certificados_internos");
		this.grpInstalaCert = this.getSysUserGroup("sn_disco_certmgmt.BNB_instalacao_certificados");
	},

	isMemberOfCertExterno: function () {
		return this._isMemberOfGroup(this.grpCertExterno);
	},

	isMemberOfCertInterno: function () {
		return this._isMemberOfGroup(this.grpCertInterno);
	},

	isMemberOfInstalaCert: function () {
		return this._isMemberOfGroup(this.grpInstalaCert);
	},

	// Obtem registro da sys_user_group a partid do nome de uma property com o nome do grupo
	getSysUserGroup: function (groupNameProperty) {
		var groupName = gs.getProperty(groupNameProperty, null);

		if (!groupName) {
			throw Error("Propriedade não foi configurada corretamente:  " + groupNameProperty);
		}

		var sysUserGroupGQ = new global.GlideQuery("sys_user_group")
			.getBy({ name: groupName }, ["sys_id", "name"])
			.orElse({ sys_id: null });

		if (!sysUserGroupGQ.sys_id) {
			throw Error("Propriedade <" + groupNameProperty + "> aponta para grupo não existente:  " + groupName);
		}

		return sysUserGroupGQ;
	},

	_isMemberOfGroup: function (sysUserGroup) {
		if (!gs.getUser()) {
			throw Error("Chamada de função inválida - deve existir usuário logado. Propriedade: " + groupNameProperty);
		}
		var isMember = gs.getUser().isMemberOf(sysUserGroup.name);
		if (!isMember) {
			throw Error("Essa função só está disponível para usuários do grupo " + sysUserGroup.name);
		}
		return true;
	},

	type: 'BNBCertUserUtils'
};
